请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-104

=== 用户原始指令 (query.txt) ===
帮我弄个内存清理卡，要有图，点一下能跳应用，能从日历读日程，看到红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个内存清理卡，要有图，点一下能跳应用，能从日历读日程，看到红色危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModel": {
    "value": {
      "memory": {
        "title": "内存危险",
        "usedText": "91%",
        "hint": "建议立即清理",
        "actionText": "去清理",
        "icon": "assets/freeclip2-memory-clean.png"
      },
      "data": {
        "calendar": {
          "items": []
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "memory_clean_icon",
      "src": "assets/freeclip2-memory-clean.png",
      "use": "memory cleanup icon",
      "description": "内存清理图标，用于表达手机存储和加速清理状态。",
      "bindTo": "/memory/icon",
      "static": true
    }
  ]
}

